head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.dt_input_obj = {};
    dt_input_obj.excel_upload_path = "jsp/dtinputPivotExcelUpload.jsp";
    dt_input_obj.img_leaf = "ext/images/nsi/com/base/df_tt4.gif";
    dt_input_obj.img_expand = "ext/images/nsi/com/base/expand.gif";
    //dt_input_obj.img_collapse		= "ext/images/nsi/com/base/collapse.gif";
    dt_input_obj.img_collapse = "ext/images/nsi/com/base/df_tt4.gif";
    dt_input_obj.prd_sort_order = ""; // 피벗 그리드의 시점 표시 순서
    dt_input_obj.char_itm_sort_order = ""; // 피벗 그리드의 항목 표시 순서
    dt_input_obj.ov_l1_sort_order = ""; // 피벗 그리드의 분류1의 분류값 표시 순서
    dt_input_obj.ov_l2_sort_order = ""; // 피벗 그리드의 분류2의 분류값 표시 순서
    dt_input_obj.ov_l3_sort_order = ""; // 피벗 그리드의 분류3의 분류값 표시 순서
    dt_input_obj.ov_l4_sort_order = ""; // 피벗 그리드의 분류4의 분류값 표시 순서
    dt_input_obj.ov_l5_sort_order = ""; // 피벗 그리드의 분류5의 분류값 표시 순서
    dt_input_obj.ov_l6_sort_order = ""; // 피벗 그리드의 분류6의 분류값 표시 순서
    dt_input_obj.ov_l7_sort_order = ""; // 피벗 그리드의 분류7의 분류값 표시 순서
    dt_input_obj.ov_l8_sort_order = ""; // 피벗 그리드의 분류8의 분류값 표시 순서
    dt_input_obj.dt_input_exec_at = false; // 수치입력 클릭 여부
    dt_input_obj.one_measure_at = false; // 단일항목 여부
    dt_input_obj.cur_make_at = ""; //Y:지속, N:시계열단절, B:백업통계표
    // 화면구성 정보에서 컬럼 명을 건네주는 함수
    dt_input_obj.get_col_name = function(col_name) {
        window.rtn_val = "";
        if (col_name.indexOf("dim1_cd") != -1) {
            rtn_val = "ovL1Id";
        } else if (col_name.indexOf("dim2_cd") != -1) {
            rtn_val = "ovL2Id";
        } else if (col_name.indexOf("dim3_cd") != -1) {
            rtn_val = "ovL3Id";
        } else if (col_name.indexOf("dim4_cd") != -1) {
            rtn_val = "ovL4Id";
        } else if (col_name.indexOf("dim5_cd") != -1) {
            rtn_val = "ovL5Id";
        } else if (col_name.indexOf("dim6_cd") != -1) {
            rtn_val = "ovL6Id";
        } else if (col_name.indexOf("dim7_cd") != -1) {
            rtn_val = "ovL7Id";
        } else if (col_name.indexOf("dim8_cd") != -1) {
            rtn_val = "ovL8Id";
        } else if (col_name.indexOf("measure_cd") != -1) {
            rtn_val = "charItmId";
        } else if (col_name.indexOf("prd_de") != -1) {
            rtn_val = "prdNm";
        } else {
            rtn_val = col_name;
        }
        return rtn_val;
    };
    // 주기, 시점, 구성정보가 파라메터에 있는 경우 자동으로 수치입력을 실행 할지 여부
    dt_input_obj.auto_dt_input = {
        auto: false,
        prd_se: "" // 주기
            ,
        strt_de: "" // 시작시점
            ,
        end_de: "" // 종료시점
            ,
        scr_id: "" // 화면구성정보
            ,
        file_nm: "" // 엑셀파일 경로 및 파일명
            ,
        sheet: "" // 시트명
            ,
        strt_row: "" // 시작 열
            ,
        strt_col: "" // 시작 행
            ,
        end_col: "" // 종료 행
    };
    // 정렬 순서
    dt_input_obj.fn_get_order = function(col_id) {
        switch (col_id) {
            case "prdNm":
                return dt_input_obj.prd_sort_order;
                break;
            case "charItmId":
                return dt_input_obj.char_itm_sort_order;
                break;
            case "ovL1Id":
                return dt_input_obj.ov_l1_sort_order;
                break;
            case "ovL2Id":
                return dt_input_obj.ov_l2_sort_order;
                break;
            case "ovL3Id":
                return dt_input_obj.ov_l3_sort_order;
                break;
            case "ovL4Id":
                return dt_input_obj.ov_l4_sort_order;
                break;
            case "ovL5Id":
                return dt_input_obj.ov_l5_sort_order;
                break;
            case "ovL6Id":
                return dt_input_obj.ov_l6_sort_order;
                break;
            case "ovL7Id":
                return dt_input_obj.ov_l7_sort_order;
                break;
            case "ovL8Id":
                return dt_input_obj.ov_l8_sort_order;
                break;
            default:
                return "";
                break;
        }
    };
    // 화면 구성 설정
    dt_input_obj.fn_stbl_scr_make = function(scr_info) {
        window.vals = "displayDtVal";
        window.cols = "";
        window.rows = "";
        window.cls = "";
        window.exclude_hidden_list = "";
        window.fitler_option_arr = [{
            type: "row",
            colIndex: "objVarId",
            key: "",
            condition: "and"
        }, {
            type: "row",
            colIndex: "ftnValAt",
            key: "1",
            condition: "and"
        }];
        window.field_option_arr = [];
        // 분류 숨김용 변수
        window.not_exclude_hidden_arr = [];
        // 장기 시계열, 시계열표, 기본통계표
        if (scr_info.length <= 0) {
            // 시점 필드 설정
            window.prd_field_option = {
                id: "prdNm",
                sortOrder: dt_input_obj.fn_get_order("prdNm"),
                representativeValue: "",
                dragToHidden: "false"
            };
            field_option_arr.push(prd_field_option);
            // 항목 필드 설정
            window.char_itm_field_option = {
                id: "charItmId",
                sortOrder: dt_input_obj.fn_get_order("charItmId"),
                representativeValue: "",
                dragToHidden: "false"
            };
            field_option_arr.push(char_itm_field_option);
            // 분류 필드 설정
            for (var cls_index = 0; cls_index < dl_cls.getRowCount(); cls_index++) {
                window.cls_info = dl_cls.getRowJSON(cls_index); // 분류 정보
                window.cls_id = "ovL" + cls_info.varOrdSn + "Id"; // 분류 코드
                // 해당 분류의 필드 설정
                window.field_option = {
                    id: cls_id,
                    sortOrder: dt_input_obj.fn_get_order(cls_id),
                    representativeValue: "",
                    dragToHidden: "false"
                };
                // 필터 해제
                dl_stbl_scr_itm.removeColumnFilterAll();
                // 분류 필터 적용
                fitler_option_arr[0].key = cls_info.objVarId;
                dl_stbl_scr_itm.setColumnFilter(fitler_option_arr[0]);
                window.cls_data_cnt = dl_stbl_scr_itm.getRowCount();
                // 대표값 필터 적용
                dl_stbl_scr_itm.setColumnFilter(fitler_option_arr[1]);
                // 대표값이 있는 경우 먼저 대표값으로 설정
                window.ftn_val_at_cnt = dl_stbl_scr_itm.getRowCount();
                if (ftn_val_at_cnt == 1) {
                    window.ftn_val_json = dl_stbl_scr_itm.getRowJSON(0);
                    field_option.representativeValue = ftn_val_json.itmId;
                    field_option.dragToHidden = "true";
                }
                // 대표값이 없으면서 분류값이 한개인 경우 해당 분류값으로 설정
                else if (cls_data_cnt == 1) {
                    dl_stbl_scr_itm.removeColumnFilter("ftnValAt");
                    window.ftn_val_json = dl_stbl_scr_itm.getRowJSON(0);
                    field_option.representativeValue = ftn_val_json.itmId;
                    field_option.dragToHidden = "true";
                }
                dl_stbl_scr_itm.removeColumnFilterAll();
                field_option_arr.push(field_option);
                // 피벗 표측 설정
                cls += cls_id;
                if (cls_index != dl_cls.getRowCount() - 1) {
                    cls += ",";
                }
            }
            // 1:기본통계표, 2:장기시계열표(표측), 3:시계열표(표두)
            window.view_mode = sel_view_type.getValue();
            // 기본통계표 : 시점,항목은 표두, 분류는 표측
            if (view_mode == 1) {
                // 표두 설정
                // 단일 항목이면서 통계표명에 포함되는 경우 항목을 안보이게 수정
                if (dt_input_obj.one_measure_at) {
                    cols = "prdNm";
                } else {
                    cols = "prdNm,charItmId";
                }
                // 표측 설정 : 분류 설정
                rows = cls;
            }
            // 장기시계열표(표측) : 항목만 표두, 나머지 표측
            else if (view_mode == 2) {
                // 표두 설정 : 항목
                cols = "charItmId";
                // 표측 설정 : 시점, 분류 설정
                rows = "prdNm," + cls;
            }
            // 장기시계열표(표두) : 시점만 표두, 나머지 표측
            else if (view_mode == 3) {
                // 표두 설정 : 시점
                cols = "prdNm";
                // 표측 설정 : 분류, 항목 설정
                rows = cls + ",charItmId";
            }
        }
        // 구성정보가 있는 경우
        else {
            // 표두 : 1212510, 표측 : 1212511
            for (var idx = 0; idx < scr_info.length; idx++) {
                window.scr = scr_info[idx];
                if (scr.code != "13999000") {
                    window.col_name = dt_input_obj.get_col_name(scr.colname);
                    if (
                        col_name == "prdNm" ||
                        col_name == "charItmId" ||
                        col_name == "ovL1Id" ||
                        col_name == "ovL2Id" ||
                        col_name == "ovL3Id" ||
                        col_name == "ovL4Id" ||
                        col_name == "ovL5Id" ||
                        col_name == "ovL6Id" ||
                        col_name == "ovL7Id"
                    ) {
                        window.field_option = {
                            id: col_name,
                            sortOrder: dt_input_obj.fn_get_order(col_name),
                            representativeValue: "",
                            dragToHidden: "false"
                        };
                        if (col_name.indexOf("ovL") > -1) {
                            // 필터 해제
                            dl_stbl_scr_itm.removeColumnFilterAll();
                            // 분류 필터 적용
                            fitler_option_arr[0].key = scr.code;
                            dl_stbl_scr_itm.setColumnFilter(fitler_option_arr[0]);
                            window.cls_data_cnt = dl_stbl_scr_itm.getRowCount();
                            // 대표값 필터 적용
                            dl_stbl_scr_itm.setColumnFilter(fitler_option_arr[1]);
                            // 대표값이 있는 경우 먼저 대표값으로 설정
                            window.ftn_val_at_cnt = dl_stbl_scr_itm.getRowCount();
                            if (ftn_val_at_cnt == 1) {
                                window.ftn_val_json = dl_stbl_scr_itm.getRowJSON(0);
                                field_option.representativeValue = ftn_val_json.itmId;
                                field_option.dragToHidden = "true";
                            }
                            // 대표값이 없으면서 분류값이 한개인 경우 해당 분류값으로 설정
                            else if (cls_data_cnt == 1) {
                                dl_stbl_scr_itm.removeColumnFilter("ftnValAt");
                                window.ftn_val_json = dl_stbl_scr_itm.getRowJSON(0);
                                field_option.representativeValue = ftn_val_json.itmId;
                                field_option.dragToHidden = "true";
                            }
                            dl_stbl_scr_itm.removeColumnFilterAll();
                        }
                        if (scr.arrySe.trim() == "1212511") {
                            if (rows.indexOf(col_name) == -1) {
                                if (rows != "") {
                                    rows += ",";
                                }
                                rows += col_name;
                            }
                        } else if (scr.arrySe.trim() == "1212510") {
                            if (cols.indexOf(col_name) == -1) {
                                if (cols != "") {
                                    cols += ",";
                                }
                                cols += col_name;
                            }
                        } else {
                            if (col_name.indexOf("ovL") > -1) {
                                not_exclude_hidden_arr.push(col_name);
                            }
                        }
                        field_option_arr.push(field_option);
                    }
                }
            }
        }
        for (var idx = not_exclude_hidden_arr.length - 1; idx >= 0; idx--) {
            window.col = not_exclude_hidden_arr[idx];
            if (col.indexOf("ovL") > -1) {
                window.varOrdSn = col.substring(3, 4);
                window.match_at = dl_cls.getMatchedJSON("varOrdSn", varOrdSn, true, 0, dl_cls.getRowCount());
                if (match_at.length <= 0) {
                    not_exclude_hidden_arr.slice(idx, 1);
                }
            }
        }
        window.rows_arr = rows.split(",");
        window.cols_arr = cols.split(",");
        // 나머지 컬럼 사용안하게 처리
        window.piv_col_info_arr = piv_virtl_dt.columnInfoList;
        for (var col_idx = 0; col_idx < piv_col_info_arr.length; col_idx++) {
            window.col_id = piv_col_info_arr[col_idx].id;
            window.match_at = false;
            for (var row_idx = 0; row_idx < rows_arr.length; row_idx++) {
                if (rows_arr[row_idx] == col_id) {
                    match_at = true;
                }
            }
            if (!match_at) {
                for (var col_arr_idx = 0; col_arr_idx < cols_arr.length; col_arr_idx++) {
                    if (cols_arr[col_arr_idx] == col_id) {
                        match_at = true;
                    }
                }
            }
            if (!match_at) {
                for (var not_exclude_hidden_arr_idx = 0; not_exclude_hidden_arr_idx < not_exclude_hidden_arr.length; not_exclude_hidden_arr_idx++) {
                    if (not_exclude_hidden_arr[not_exclude_hidden_arr_idx] == col_id) {
                        match_at = true;
                    }
                }
            }
            if (!match_at && vals.indexOf(col_id) > -1) {
                match_at = true;
            }
            if (!match_at) {
                if (exclude_hidden_list != "") {
                    exclude_hidden_list += ",";
                }
                exclude_hidden_list += col_id;
            }
        };
        // 피벗 Option 및 FieldOption 설정
        piv_virtl_dt.setFieldOption(field_option_arr);
        piv_virtl_dt.setOption({
            "rows": rows,
            "cols": cols,
            "vals": vals,
            "excludeHiddenList": exclude_hidden_list
        });
        //piv_virtl_dt.bind("onrefresh",dt_input_obj.fn_get_scr);
    };
    // 시점 포멧 함수
    dt_input_obj.fn_prd_formatter = function(prd_de) {
        window.view_prd_de = ""; // 리턴 변수
        if (prd_de.length == 8) {
            view_prd_de = prd_de.substring(0, 4) + "." + prd_de.substring(4, 6) + "." + prd_de.substring(6, 8);
        } else if (prd_de.length == 6) {
            view_prd_de = prd_de.substring(0, 4) + "." + prd_de.substring(4, 6);
        } else {
            view_prd_de = prd_de;
        }
        return view_prd_de;
    };
    dt_input_obj.custom = function() {
        // 마우스 우클릭 메뉴 콜백 함수
        // 메뉴 선택 인덱스만 추가함
        piv_virtl_dt.callContextMenuAPI = function(_68, _69) {
            ["WebSquare.uiplugin.pivotLayoutController.prototype.callContextMenuAPI"];
            try {
                // _69 : 선택 셀 정보
                // _68 : 메뉴 선택 인덱스
                this.contextMenu.callbackFunctionList[_68](_69, _68);
            } catch (e) {
                WebSquare.exception.printStackTrace(e);
            }
        };
        // 피벗 그리드 숨김영역에 이동시 이벤트
        piv_virtl_dt.movePivotHiddenList = function(_7a) {
            ["WebSquare.uiplugin.pivotLayoutController.prototype.movePivotHiddenList"];
            try {
                this.options.rows = this.pivotData.rowAttrs.join(",");
                this.options.cols = this.pivotData.colAttrs.join(",");
                window._7b = _7a[0];
                window._7c = _7a[1] - 0;
                var _7d;
                for (var i = 0; i < this.columnInfoList.length; i++) {
                    if (this.columnInfoList[i].name == _7a[2] || this.columnInfoList[i].id == _7a[2]) {
                        _7d = this.columnInfoList[i].id;
                        if (this.columnInfoList[i].representativeValue && this.columnInfoList[i].dragToHidden != "false") {
                            this.columnInfoList[i].inclusions = this.columnInfoList[i].representativeValue;
                            this.columnInfoList[i].hidden = true;
                        }
                        if (this.columnInfoList[i].dragToHidden == "false") {
                            window.msg = "";
                            if (this.columnInfoList[i].id == "prdNm" || this.columnInfoList[i].id == "charItmId") {
                                msg = "\"항목\", \"시점\"은 숨김영역으로 이동 할 수 없습니다.";
                            } else {
                                msg = "\"" + this.columnInfoList[i].name + "\"" +
