                } else {
                    this.options.cols = _81.join(",");
                }
                this.refreshItemset({
                    refresh: true,
                    type: "render"
                });
            } catch (e) {
                WebSquare.exception.printStackTrace(e);
            }
        };
        // 피벗그리드 셀에서 입력 후 이벤트
        piv_virtl_dt.endCellEditMode = function() {
            ["WebSquare.uiplugin.pivotCellController.prototype.endCellEditMode"];
            try {
                window._7 = this.editingTD.getAttribute("data-coordinate").split(",");
                window._8 = _7[0] - 0;
                window._9 = _7[1] - 0;
                window._a = this.getInput(this.editingTD);
                window._b = _a.getValue();
                window._c = this.getValue(_8, _9);
                this.moveInputRenderTo(this.render);
                _a.hide();
                if (_b == "") {
                    newValue = _b;
                } else {
                    if (this.options.valueDataType == "number") {
                        _b = _b.wq_trim();
                        pattern = /^[+|-]?(([1-9]{1}[0-9]*)|[0])([\.][0-9]+)?$/;
