        if (!WebSquare.util.isIEAllVersion()) {
            if (WebSquare.core.browserCheck.safari) {
                piv_virtl_dt.event.addListener(WebSquare.getBody().render, "onbeforecopy", piv_virtl_dt.event.bindAsEventListener(piv_virtl_dt, piv_virtl_dt.handleBeforeCopyEvent));
                piv_virtl_dt.event.addListener(WebSquare.getBody().render, "oncopy", piv_virtl_dt.event.bindAsEventListener(piv_virtl_dt, piv_virtl_dt.handleCopyEvent));
            } else {
                piv_virtl_dt.event.addListener(piv_virtl_dt.render, "oncopy", piv_virtl_dt.event.bindAsEventListener(piv_virtl_dt, piv_virtl_dt.handleCopyEvent));
            }
        }
    };
