                        dt_input_obj.ov_l7_sort_order = sort_order;
                        break;
                    case "8":
                        dt_input_obj.ov_l8_sort_order = sort_order;
                        break;
                    default:
                        break;
                }
            } else {
                if (msg != "") {
                    msg += ",";
                }
                msg += "\"" + cls.scrKor + "\"";
