    // 피벗 그리드컬럼 포멧터
    dt_input_obj.fn_column_name_formatter = function(col_id) {
        window.col_name = "";
        // 한글보기 : 0, 영문보기 : 1, 코드보기 : 2, 코드 + 한글보기 : 3, 코드 + 영문보기 : 4 
        window.lang_mode = sel_lang_mode.getValue();
        window.name = "";
        window.eng_name = "";
        window.code = "";
        if (col_id.indexOf("charItm") > -1) {
            name = "항목";
            eng_name = "Measure";
            code = "13999001";
        } else if (col_id.indexOf("prd") > -1) {
            name = "시점";
            eng_name = "Period";
            code = "prdNm";
        } else if (col_id == "displayDtVal") {
            name = "데이터";
            eng_name = "data";
            code = "";
        } else {
            window.cls_cnt = dl_cls.getRowCount();
            window.var_ord_sn = WebSquare.util.parseInt(col_id.substring(3, 4), 0);
            window.cls = dl_cls.getMatchedJSON("varOrdSn", var_ord_sn, true, 0, cls_cnt);
            if (cls.length > 0) {
                name = cls[0].scrKor;
                eng_name = cls[0].scrEng;
                code = cls[0].objVarId;
            }
        }
        switch (lang_mode) {
            case "0":
                col_name = name;
                break;
            case "1":
                col_name = eng_name;
                break;
            case "2":
                if (col_id == "displayDtVal") {
                    col_name = name;
                } else {
                    col_name = code;
                }
                break;
            case "3":
                if (col_id == "displayDtVal") {
                    col_name = name;
                } else {
                    col_name = code + " " + name;
                }
                break;
            case "4":
                if (col_id == "displayDtVal") {
                    col_name = eng_name;
                } else {
                    col_name = code + " " + eng_name;
                }
                break;
        };
        return col_name;
    };
    // 표측 및 표두 포멧터
    dt_input_obj.fn_head_data_name_formatter = function(dl_row_idx, col_id, name) {
        window.option = piv_virtl_dt.getOption();
        window.rows = option.rows; // 표측
        window.lang_mode = sel_lang_mode.getValue();
        window.rows_json = dl_dt_virtl.getRowJSON(dl_row_idx);
        // 한글보기 : 0, 영문보기 : 1, 코드보기 : 2, 코드 + 한글보기 : 3, 코드 + 영문보기 : 4
        if (col_id.indexOf("ovL") > -1 || col_id.indexOf("charItmId") > -1) {
            window.code = NsiCom.fn_replace_all(col_id, "Id", "");
            window.rtn_val = "";
            window.unit = "";
            switch (lang_mode) {
                case "0":
                    rtn_val = rows_json[code + "Kor"];
                    if (col_id.indexOf("charItmId") > -1) {
                        if (!NsiCom.fn_is_empty(rows_json[code + "UnitKor"])) {
                            unit = " (" + NsiCom.fn_trim(rows_json[code + "UnitKor"]) + ")";
                            rtn_val += unit;
                        }
                    }
                    break;
                case "1":
                    rtn_val = rows_json[code + "Eng"];
                    if (col_id.indexOf("charItmId") > -1) {
                        if (!NsiCom.fn_is_empty(rows_json[code + "UnitEng"])) {
                            unit = " (" + NsiCom.fn_trim(rows_json[code + "UnitEng"]) + ")";
                            rtn_val += unit;
                        }
                    }
                    break;
                case "2":
                    rtn_val = rows_json[code + "Id"];
                    if (col_id.indexOf("charItmId") > -1) {
                        if (!NsiCom.fn_is_empty(rows_json[code + "Unit"])) {
                            unit = " (" + NsiCom.fn_trim(rows_json[code + "Unit"]) + ")";
                            rtn_val += unit;
                        }
                    }
                    break;
                case "3":
                    rtn_val = rows_json[code + "Id"] + " " + rows_json[code + "Kor"];
                    if (col_id.indexOf("charItmId") > -1) {
                        if (!NsiCom.fn_is_empty(rows_json[code + "UnitKor"])) {
                            unit = " (" + NsiCom.fn_trim(rows_json[code + "UnitKor"]) + ")";
                            rtn_val += unit;
                        }
                    }
                    break;
                default:
                    rtn_val = rows_json[code + "Id"] + " " + rows_json[code + "Eng"];
                    if (col_id.indexOf("charItmId") > -1) {
                        if (!NsiCom.fn_is_empty(rows_json[code + "UnitEng"])) {
                            unit = " (" + NsiCom.fn_trim(rows_json[code + "UnitEng"]) + ")";
                            rtn_val += unit;
                        }
                    }
                    break;
            }
            // 유니코드를 글자로 변경
            // 유니코드 이스케이프 정규식
            window.unicode_reg = /\\u[a-fA-F0-9]{4}/g;
            window.reg_rtn = rtn_val.match(unicode_reg);
            if (reg_rtn != null && reg_rtn.length > 0) {
                for (var reg_idx in reg_rtn) {
                    window.new_unicode = String.fromCharCode(reg_rtn[reg_idx].replace("\\u", "0x"));
                    rtn_val = rtn_val.replace(reg_rtn[reg_idx], new_unicode);
                }
            }
            // TODO :: 컬럼 숨김 후 피벗 옵션 갱신 확인
            if (rows.indexOf(col_id) > -1 && col_id.indexOf("ovL") > -1) {
                window.lvl = rows_json[code + "Co"];
                window.leaf = rows_json[code + "Leaf"];
                window.blank = "";
                window.data = rtn_val;
                window.image_name = "";
                for (var idx = 0; idx < ((WebSquare.util.parseInt(lvl, 1) - 1) * 4); idx++) {
                    blank += "&nbsp;";
                }
                if (leaf == "0") {
                    image_name = "<img src='" + dt_input_obj.img_leaf + "' style='vertical-align: middle;'></img>&nbsp;&nbsp;";
                } else if (leaf == "1") {
                    //image_name = "<img src='ext/images/nsi/com/base/collapse.gif' style='vertical-align: middle;'></img>&nbsp;&nbsp;";
                    image_name = "<img src='" + dt_input_obj.img_collapse + "' style='vertical-align: middle;'></img>&nbsp;&nbsp;";
                } else if (leaf == "2") {
                    image_name = "<img src='" + dt_input_obj.img_expand + "' style='vertical-align: middle;'></img>&nbsp;&nbsp;";
                }
                rtn_val = blank + image_name + data;
            }
            return rtn_val;
        } else if (col_id == "prdNm") {
            window.rtn_val = "";
            window.smblCn = "";
            window.recd_prd = dl_recd_prd.getMatchedJSON("prdDe", rows_json["prdDe"], true, 0, dl_recd_prd.getRowCount());
            if (recd_prd.length > 0) {
                if (recd_prd[0].smblCn != "") {
                    smblCn = " " + recd_prd[0].smblCn + ")";
                }
            }
            switch (lang_mode) {
                case "0":
                case "1":
                    rtn_val = NsiCom.fn_replace_all(rows_json["prdNm"], "_", "/");
                    break;
                case "2":
                    rtn_val = rows_json["prdSe"] + rows_json["prdDe"];
                    break;
                default:
                    rtn_val = rows_json["prdSe"] + rows_json["prdDe"] + " " + NsiCom.fn_replace_all(rows_json["prdNm"], "_", "/");
                    break;
            }
            return rtn_val + smblCn;
        } else if (col_id == "value") {
            if (lang_mode == "0" || lang_mode == "2" || lang_mode == "3") {
                return "데이터";
            } else {
                return "data";
            }
        } else {
            return name;
        }
    };
    // 데이터 포멧터
    dt_input_obj.fn_number_formatter = function(info) {
        window.row_idx = piv_virtl_dt.getDataListRowIndex(info.rowIndex, info.colIndex);
        window.row_json = dl_dt_virtl.getRowJSON(row_idx);
        window.rtn = info.value;
        window.smblCn = row_json.smblCn;
        if (rtn == null || rtn == "") {
            rtn = "";
        }
        // 유니코드를 글자로 변경
        // 유니코드 이스케이프 정규식
        window.unicode_reg = /\\u[a-fA-F0-9]{4}/g;
        window.reg_rtn = rtn.match(unicode_reg);
        if (reg_rtn != null && reg_rtn.length > 0) {
            for (var reg_idx in reg_rtn) {
                window.new_unicode = String.fromCharCode(reg_rtn[reg_idx].replace("\\u", "0x"));
                rtn = rtn.replace(reg_rtn[reg_idx], new_unicode);
            }
        }
        window.reg_smbl = smblCn.match(unicode_reg);
        if (reg_smbl != null && reg_smbl.length > 0) {
            for (var reg_idx in reg_smbl) {
                window.new_unicode = String.fromCharCode(reg_smbl[reg_idx].replace("\\u", "0x"));
                smblCn = smblCn.replace(reg_smbl[reg_idx], new_unicode);
            }
        }
        // 정보원 [ 김기만 사무관 요청 ] - 2017.08.21
        // 통계부호 HTML과 동일하게 표시 , 비밀보호(X),  미상(...), 수치없음(-)은 통계부호만 보이게 수정 요청
        if (smblCn != null && NsiCom.fn_trim(smblCn) != "") {
            if (smblCn != "e" && smblCn != "p" && smblCn != "▽" && smblCn != "*" && smblCn != "**") {
                if (smblCn == "x") {
                    smblCn = smblCn.toUpperCase();
                }
                return smblCn;
            } else {
                smblCn = " <sup>" + smblCn + "</sup>";
                // 항목 타입이 문자인 경우는 바로 출력
                if (NsiCom.fn_trim(row_json.charItmKd) == "1210514") {
                    // 숫자 형식이 아닌 경우
                    if (isNaN(rtn)) {
                        return rtn + smblCn;
                    }
                    // 숫자 형식인 경우
                    else {
                        window.parts = rtn.toString().split(".");
                        rtn = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (parts[1] ? "." + parts[1] : "");
                        return rtn + smblCn;
                    }
                }
                // 항목 타입이 숫자인 경우는 ,붙여서 출력
                else {
                    window.parts = rtn.toString().split(".");
                    rtn = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (parts[1] ? "." + parts[1] : "");
                    return rtn + smblCn;
                }
            }
        } else {
            // 항목 타입이 문자인 경우는 바로 출력
            if (NsiCom.fn_trim(row_json.charItmKd) == "1210514") {
                // 숫자 형식이 아닌 경우
                if (isNaN(rtn)) {
                    return rtn;
                }
                // 숫자 형식인 경우
                else {
                    window.parts = rtn.toString().split(".");
                    rtn = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (parts[1] ? "." + parts[1] : "");
                    return rtn;
                }
                return rtn;
            }
            // 항목 타입이 숫자인 경우는 ,붙여서 출력
            else {
                window.parts = rtn.toString().split(".");
                rtn = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (parts[1] ? "." + parts[1] : "");
                return rtn;
            }
        }
    };
    // 입력값이 숫자 형태인지 확인
    dt_input_obj.fn_number_chk = function(char_itm_kd, data) {
        if (NsiCom.fn_is_empty(data)) {
            return "blank";
        }
        // 통계부호만 있는 경우
        if (
            data.trim() == "[...]" ||
            data.trim() == "[-]" ||
            data.trim() == "[e]" ||
            data.trim() == "[p]" ||
            data.trim() == "[x]" ||
            data.trim() == "[▽]" ||
            data.trim() == "[*]" ||
            data.trim() == "[**]"
        ) {
            return "smbl";
        }
        // 통계부호가 []로 안되어 있는 경우 
        if (
            data.trim() == "..." ||
            data.trim() == "-" ||
            data.trim() == "e" ||
            data.trim() == "p" ||
            data.trim() == "x" ||
            data.trim() == "▽" ||
            data.trim() == "*" ||
            data.trim() == "**"
        ) {
            return "smbl_etc";
        }
        // 문자인 경우 etc로 수행
        if (char_itm_kd == "1210514") {
            return "etc";
        }
        // 콤마(,)만 존재하는 지 확인
        if (data.indexOf(",") > -1 && NsiCom.fn_replace_all(data, ",", "") == "") {
            return "etc";
        }
        // 콤마(,) 제거
        data = NsiCom.fn_replace_all(data, ",", "");
        // 문자인 경우
        if (isNaN(data)) {
            // [ 와 ]가 모두 있는 경우
            if (data.indexOf("[") > -1 && data.indexOf("]") > -1) {
                window.str_len = WebSquare.util.parseInt(data.length, 0);
                window.first_idx = WebSquare.util.parseInt(data.indexOf("["), -1);
                window.tmp_data = data.substring(first_idx + 1, str_len);
                window.last_idx = WebSquare.util.parseInt(tmp_data.indexOf("]"), -1);
                window.smbl = tmp_data.substring(0, last_idx).trim();
                window.dtval = data.substring(0, first_idx).trim();
                if (
                    (smbl == "..." ||
                        smbl == "-" ||
                        smbl == "e" ||
                        smbl == "p" ||
                        smbl == "x" ||
                        smbl == "▽" ||
                        smbl == "*" ||
                        smbl == "**"
                    ) && !isNaN(NsiCom.fn_replace_all(dtval, " ", ""))
                ) {
                    return "number_smbl";
                } else {
                    return "etc";
                }
            }
            // 
            else {
                // []가 짝이 맞는지 확인 : 둘중에 하나만 있으면 etc
                if (
                    (data.indexOf("[") <= -1 && data.indexOf("]") > -1) ||
                    (data.indexOf("[") > -1 && data.indexOf("]") <= -1)
                ) {
                    return "etc";
                }
                // 숫자와 통계부호가 []가 없는 경우
                else {
                    window.data_arr = [];
                    if (data.indexOf(" ") > -1) {
                        data_arr = data.split(" ");
                        window.data_len = data_arr.length - 1;
                        if (
                            data_arr[data_arr.length - 1] === "..." ||
                            data_arr[data_arr.length - 1] === "-" ||
                            data_arr[data_arr.length - 1] === "e" ||
                            data_arr[data_arr.length - 1] === "p" ||
                            data_arr[data_arr.length - 1] === "x" ||
                            data_arr[data_arr.length - 1] === "▽" ||
                            data_arr[data_arr.length - 1] === "**" ||
                            data_arr[data_arr.length - 1] === "*"
                        ) {
                            window.tmp_dt = 0;
                            for (var arr_idx = 0; arr_idx < (data_arr.length - 2); arr_idx++) {
                                tmp_dt += data_arr[arr_idx];
                            }
                            if (isNaN(NsiCom.fn_replace_all(tmp_dt, " ", ""))) {
                                return "etc";
                            } else {
                                return "number_smbl_etc";
                            }
                        } else {
                            if (isNaN(NsiCom.fn_replace_all(data, " ", ""))) {
                                return "etc";
                            } else {
                                return "number";
                            }
                        }
                    } else {
                        if (isNaN(data)) {
                            return "etc";
                        } else {
                            return "number";
                        }
                    }
                }
            }
        }
        // 숫자인 경우
        else {
            return "number";
        }
    };
    // 숫자
    dt_input_obj.fn_get_number = function(data) {
        data = NsiCom.fn_replace_all(data, " ", "");
        if (data.indexOf(",") > -1) {
            data = NsiCom.fn_replace_all(data, ",", "");
        }
        if (data.indexOf("+") > -1) {
            data = NsiCom.fn_replace_all(data, "\\+", "");
        }
        if (data.indexOf(".") > -1) {
            data = data.replace(/([0]+|[\.][0]+)$/, "");
        }
        if (/^[+|-]?[0]+([\.][0]*)?$/.test(data)) {
            data = "0";
        }
        return data;
    };
    // 통계부호
    dt_input_obj.fn_get_smbl = function(data) {
        window.smbl_json = dl_smbl.getAllJSON();
        window.str_len = WebSquare.util.parseInt(data.length, 0);
        window.first_idx = WebSquare.util.parseInt(data.indexOf("["), -1);
        window.tmp_data = data.substring(first_idx + 1, str_len);
        window.last_idx = WebSquare.util.parseInt(tmp_data.indexOf("]"), -1);
        window.rtn_data = "";
        tmp_data = tmp_data.substring(0, last_idx).trim();
        for (var idx = 0; idx < smbl_json.length; idx++) {
            if (smbl_json[idx].code === tmp_data) {
                rtn_data = smbl_json[idx].code;
                break;
            }
        }
        if (rtn_data != "") {
            return NsiCom.fn_trim(rtn_data);
        } else {
            return NsiCom.fn_trim(data);
        }
    };
    // 엑셀업로드 및 엑셀 복사하여 & 붙여넣기 데이터를 넣는 함수
    dt_input_obj.fn_set_dt_data = function(dl_id, row_idx, data) {
        window.value = "";
        window.smbl = "";
        window.dl_comp = WebSquare.wUnit.getObjById(dl_id);
        if (data.indexOf("…") > -1) {
            data = NsiCom.fn_replace_all(data, "…", "...");
        } else if (data.indexOf("X") > -1) {
            data = NsiCom.fn_replace_all(data, "X", "x");
        } else if (data.indexOf("E") > -1) {
            data = NsiCom.fn_replace_all(data, "E", "e");
        } else if (data.indexOf("P") > -1) {
            data = NsiCom.fn_replace_all(data, "P", "p");
        }
        window.charItmKd = dl_comp.getCellData(row_idx, "charItmKd");
        window.dta_type = dt_input_obj.fn_number_chk(charItmKd, data);
        switch (dta_type) {
            // 수치만 있는 경우
            case "number":
                value = dt_input_obj.fn_get_number(data);
                // 기존 통계부호 삭제
                smbl = "blank";
                break;
                // 통계부호만 있는 경우 
            case "smbl":
                smbl = dt_input_obj.fn_get_smbl(data);
                // 신규로 "-" 통계 부호로 들어갈 경우 수치를 삭제
                if (
                    smbl === "-" ||
                    smbl === "▽" ||
                    smbl === "*" ||
                    smbl === "**"
                ) {
                    value = "blank";
                }
                break;
                // 수치와 통계부호가 같이 있는 경우
            case "number_smbl":
                if (data.indexOf("[") > -1) {
                    window.tmp_value = data.substring(0, data.indexOf("["));
                    window.tmp_smbl = data.substring(data.indexOf("["), data.length);
                    tmp_value = NsiCom.fn_trim(tmp_value);
                    tmp_smbl = NsiCom.fn_trim(tmp_smbl);
                    value = dt_input_obj.fn_get_number(tmp_value);
                    smbl = dt_input_obj.fn_get_smbl(tmp_smbl);
                    if (
                        smbl === "-" ||
                        smbl === "▽" ||
                        smbl === "*" ||
                        smbl === "**"
                    ) {
                        value = "blank";
                    }
                } else {
                    window.smbl_json = dl_smbl.getAllJSON();
                    for (var idx = 1; idx < smbl_json.length; idx++) {
                        if (data.indexOf(smbl_json[idx].code) > -1) {
                            window.tmp_value = data.substring(0, data.indexOf(smbl_json[idx].code));
                            window.tmp_smbl = data.substring(data.indexOf(smbl_json[idx].code), data.length);
                            tmp_value = NsiCom.fn_trim(tmp_value);
                            tmp_smbl = NsiCom.fn_trim(tmp_smbl);
                            value = dt_input_obj.fn_get_number(tmp_value);
                            smbl = dt_input_obj.fn_get_smbl(tmp_smbl);
                            if (
                                smbl === "-" ||
                                smbl === "▽" ||
                                smbl === "*" ||
                                smbl === "**"
                            ) {
                                value = "blank";
                            }
                            break;
                        }
                    }
                }
                break;
            case "number_smbl_etc":
                window.smbl_json = dl_smbl.getAllJSON();
                for (var idx = 1; idx < smbl_json.length; idx++) {
                    if (data.indexOf(smbl_json[idx].code) > -1) {
                        window.tmp_value = data.substring(0, data.indexOf(smbl_json[idx].code));
                        window.tmp_smbl = data.substring(data.indexOf(smbl_json[idx].code), data.length);
                        tmp_value = NsiCom.fn_trim(tmp_value);
                        tmp_smbl = NsiCom.fn_trim(tmp_smbl);
                        value = dt_input_obj.fn_get_number(tmp_value);
                        smbl = dt_input_obj.fn_get_smbl(tmp_smbl);
                        if (
                            smbl === "-" ||
                            smbl === "▽" ||
                            smbl === "*" ||
                            smbl === "**"
                        ) {
                            value = "blank";
                        }
                        break;
                    }
                }
                break;
            case "smbl_etc":
                if (
                    data === "-" ||
                    data === "▽" ||
                    data === "*" ||
                    data === "**"
                ) {
                    value = "blank";
                }
                smbl = data;
                break;
            case "blank":
                value = "blank";
                smbl = "blank";
                break;
                // 입력형태가 다른 경우 - 문자열인 경우
            default:
                window.charItmKd = dl_comp.getCellData(row_idx, "charItmKd");
                // 항목이 기타가 아닌 경우 값을 안 넣음
                if (charItmKd != "1210514") {
                    value = "";
                    smbl = "";
                    alert(piv_virtl_dt.options.invalidMessage);
                } else {
                    // 문자열과 통계부호가 같이 있는 경우 
                    if (
                        data.indexOf("[...]") > -1 ||
                        data.indexOf("[-]") > -1 ||
                        data.indexOf("[e]") > -1 ||
                        data.indexOf("[p]") > -1 ||
                        data.indexOf("[x]") > -1 ||
                        data.indexOf("[▽]") > -1 ||
                        data.indexOf("[*]") > -1 ||
                        data.indexOf("[**]") > -1
                    ) {
                        window.srch_smbl = "";
                        if (data.indexOf("[...]") > -1) {
                            srch_smbl = "[...]";
                        } else if (data.indexOf("[-]") > -1) {
                            srch_smbl = "[-]";
                        } else if (data.indexOf("[e]") > -1) {
                            srch_smbl = "[e]";
                        } else if (data.indexOf("[p]") > -1) {
                            srch_smbl = "[p]";
                        } else if (data.indexOf("[x]") > -1) {
                            srch_smbl = "[x]";
                        } else if (data.indexOf("[▽]") > -1) {
                            srch_smbl = "[▽]";
                        } else if (data.indexOf("[*]") > -1) {
                            srch_smbl = "[*]";
                        } else if (data.indexOf("[**]") > -1) {
                            srch_smbl = "[**]";
                        }
                        // "[","]" 제거
                        smbl = NsiCom.fn_trim(data.substring(data.indexOf(srch_smbl) + 1, data.length - 1));
                        if (
                            smbl === "-" ||
                            smbl === "▽" ||
                            smbl === "*" ||
                            smbl === "**"
                        ) {
                            value = "blank";
                        } else {
                            value = NsiCom.fn_trim(data.substring(0, data.indexOf(srch_smbl)));
                        }
                    }
                    //문자열만 있는 경우
                    else {
                        value = data;
                        smbl = "blank";
                    }
                }
                break;
        }
        if (value === "blank") {
            dl_comp.setCellData(row_idx, "displayDtVal", "");
        } else if (value != "") {
            dl_comp.setCellData(row_idx, "displayDtVal", value);
        }
        if (smbl === "blank") {
            dl_comp.setCellData(row_idx, "smblCn", "");
        } else if (smbl != "") {
            dl_comp.setCellData(row_idx, "smblCn", smbl);
        }
    };
